 hit(p,ax,ay,bx,by,speed,reduced=false){const sx=bx-ax,sy=by-ay,len2=sx*sx+sy*sy;if(len2<.01)return false;const t=Math.max(0,Math.min(1,((p.x-ax)*sx+(p.y-ay)*sy)/len2)),hx=ax+t*sx,hy=ay+t*sy;let nx=p.x-hx,ny=p.y-hy,d=Math.hypot(nx,ny),radius=Math.min(90,22+speed*13);if(d>=radius)return false;const len=Math.sqrt(len2),dx=sx/len,dy=sy/len;if(d<.01){nx=-dy;ny=dx;d=1}else{nx/=d;ny/=d}const falloff=Math.pow(1-d/radius,1.4),power=(2+Math.pow(Math.min(speed,5),1.15)*13)*(reduced?.18:1)*falloff;p.vx+=(dx*.95+nx*.75)*power;p.vy+=(dy*.95+ny*.75)*power;const v=Math.hypot(p.vx,p.vy);if(v>95){p.vx*=95/v;p.vy*=95/v}p.flight=Math.max(p.flight||0,Math.min(10,2+speed*2));return true},
