(()=>{const el=document.getElementById('nameParticles'),overlay=document.createElement('canvas');overlay.className='signature-flight-layer';overlay.setAttribute('aria-hidden','true');document.body.append(overlay);const c=overlay.getContext('2d'),buffer=document.createElement('canvas'),b=buffer.getContext('2d',{willReadFrequently:true});let particles=[],w=0,h=0,ratio=1,visible=false,frame=0,last=0,previous=null,bursts=[];const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;function build(){const r=el.getBoundingClientRect();w=Math.round(r.width);h=Math.round(r.height);if(!w||!h)return;ratio=Math.min(devicePixelRatio||1,2);el.width=w*ratio;el.height=h*ratio;overlay.width=Math.round(innerWidth*ratio);overlay.height=Math.round(innerHeight*ratio);c.setTransform(ratio,0,0,ratio,0,0);buffer.width=w;buffer.height=h;b.clearRect(0,0,w,h);const main='BEN RODEN',sub='SPIRITUALITY IN THE ARTS';let mainSize=Math.min(w*.17,h*.42);b.font=`800 ${mainSize}px Arial, sans-serif`;let mainWidth=b.measureText(main).width;if(mainWidth>w*.96){mainSize*=w*.96/mainWidth;b.font=`800 ${mainSize}px Arial, sans-serif`;mainWidth=b.measureText(main).width}let subSize=Math.min(mainSize*.28,h*.12);b.font=`800 ${subSize}px Arial, sans-serif`;let subWidth=b.measureText(sub).width;if(subWidth>w*.9){subSize*=w*.9/subWidth;b.font=`800 ${subSize}px Arial, sans-serif`}const mainY=h*.36,subY=h*.72;b.fillStyle='white';b.textAlign='center';b.textBaseline='middle';b.font=`800 ${mainSize}px Arial, sans-serif`;b.fillText(main,w/2,mainY);b.font=`800 ${subSize}px Arial, sans-serif`;b.fillText(sub,w/2,subY);const data=b.getImageData(0,0,w,h).data;particles=[];const gap=w<600?3.1:4.2;for(let y=0;y<h;y+=gap)for(let x=0;x<w;x+=gap)if(data[(Math.floor(y)*w+Math.floor(x))*4+3]>140){const k=Math.random();particles.push({x,y,homeX:x,homeY:y,prevX:x,prevY:y,vx:0,vy:0,flight:0,r:(w<600?.72:1.05)+k*.32,color:k>.91?'#e8dfcc':k>.5?'#becde2':'#8da8cf'})}previous=null;bursts=[];draw();start()}
function draw(){c.clearRect(0,0,innerWidth,innerHeight);const anchor=el.getBoundingClientRect();c.save();c.translate(anchor.left,anchor.top);for(const p of particles){const speed=Math.hypot(p.vx,p.vy);if(speed>2&&!reduce){c.strokeStyle='#a8cfff';c.globalAlpha=Math.min(.55,speed/75);c.lineWidth=p.r*.8;c.beginPath();c.moveTo(p.x-p.vx*.85,p.y-p.vy*.85);c.lineTo(p.x,p.y);c.stroke()}c.globalAlpha=1;c.fillStyle=speed>10?'#e4f3ff':p.color;c.beginPath();c.arc(p.x,p.y,p.r*(1+Math.min(.4,speed/110)),0,Math.PI*2);c.fill()}for(const q of bursts){c.strokeStyle='#b4d5ff';c.globalAlpha=q.life*.24;c.lineWidth=.7;c.beginPath();c.arc(q.x,q.y,q.radius,0,Math.PI*2);c.stroke()}c.globalAlpha=1;c.restore()}
function animate(time){frame=0;if(!visible||document.hidden)return;const dt=Math.min(2,Math.max(.25,(time-last)/16.67||1));last=time;let moving=false;for(const p of particles)if(signaturePhysics.step(p,dt))moving=true;for(const q of bursts){q.radius+=q.power*dt;q.life-=.045*dt}bursts=bursts.filter(q=>q.life>0);draw();if(moving||bursts.length)frame=requestAnimationFrame(animate)}function start(){if(visible&&!frame&&!document.hidden){last=performance.now();frame=requestAnimationFrame(animate)}}
function move(e){if(e.pointerType!=='mouse'&&!e.buttons)return;const now=e.timeStamp||performance.now(),r=el.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(previous&&now-previous.t<150&&visible){const elapsed=Math.max(4,now-previous.t),speed=Math.min(5,Math.hypot(x-previous.x,y-previous.y)/elapsed);let hits=0;if(speed>.025&&Math.max(x,previous.x)>-100&&Math.min(x,previous.x)<w+100&&Math.max(y,previous.y)>-100&&Math.min(y,previous.y)<h+100){for(const p of particles)if(signaturePhysics.hit(p,previous.x,previous.y,x,y,speed,reduce))hits++;if(hits){if(speed>1&&!reduce&&bursts.length<6)bursts.push({x:Math.max(0,Math.min(w,x)),y:Math.max(0,Math.min(h,y)),radius:8,life:1,power:1+speed});start()}}}previous={x,y,t:now}}
document.addEventListener('pointermove',move,{passive:true});el.addEventListener('pointerdown',e=>{const r=el.getBoundingClientRect();previous={x:e.clientX-r.left,y:e.clientY-r.top,t:e.timeStamp||performance.now()};el.setPointerCapture(e.pointerId)});el.addEventListener('pointercancel',()=>previous=null);document.addEventListener('pointerup',e=>{if(e.pointerType!=='mouse')previous=null});addEventListener('blur',()=>previous=null);document.addEventListener('scroll',()=>{previous=null;start()},{passive:true});function scatter(){for(const p of particles){const a=Math.random()*Math.PI*2,power=(reduce?3:22)+Math.random()*(reduce?3:35);p.vx+=Math.cos(a)*power;p.vy+=Math.sin(a)*power;p.flight=reduce?0:8}start()}function reset(){previous=null;bursts=[];for(const p of particles){p.flight=0;if(reduce){p.x=p.homeX;p.y=p.homeY;p.vx=p.vy=0}else{p.vx*=.2;p.vy*=.2}}draw();start()}document.getElementById('scatterName').onclick=scatter;document.getElementById('resetName').onclick=reset;el.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();scatter()}if(e.key==='Escape')reset()};new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)start();else{if(frame)cancelAnimationFrame(frame);frame=0;previous=null;c.clearRect(0,0,innerWidth,innerHeight)}},{rootMargin:'650px'}).observe(el);document.addEventListener('visibilitychange',()=>{previous=null;start()});let timer;addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(build,150)});document.fonts.ready.then(build);})();
